{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "core_distance" not in case or "distances" not in case:
        raise ValueError("missing required field")

    nodes = case["nodes"]
    cores = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if any(not isinstance(node, str) for node in nodes):
        raise ValueError("node identifiers must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")
    node_set = set(nodes)

    if not isinstance(cores, dict) or set(cores) != node_set:
        raise ValueError("core_distance keys must match nodes")
    for node in nodes:
        value = cores[node]
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
            raise ValueError("core distances must be finite numbers")

    if not isinstance(distances, list):
        raise ValueError("distances must be a list")
    expected = len(nodes) * (len(nodes) - 1) // 2
    if len(distances) != expected:
        raise ValueError("distance matrix is incomplete or has extra edges")

    edges = []
    seen = set()
    for row in distances:
        if not isinstance(row, list) or len(row) != 3:
            raise ValueError("each distance must be a three-item list")
        left, right, distance = row
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("distance endpoints must be strings")
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("invalid distance endpoint")
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or not math.isfinite(distance):
            raise ValueError("distances must be finite numbers")
        a, b = (left, right) if left < right else (right, left)
        key = (a, b)
        if key in seen:
            raise ValueError("duplicate undirected edge")
        seen.add(key)
        weight = max(cores[left], cores[right], distance)
        edges.append((weight, a, b))

    if len(seen) != expected:
        raise ValueError("distance matrix is incomplete")
    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    index = {node: i for i, node in enumerate(nodes)}
    parent = list(range(len(nodes)))
    rank = [0] * len(nodes)

    def find(value):
        while parent[value] != value:
            parent[value] = parent[parent[value]]
            value = parent[value]
        return value

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, left, right in edges:
        if union(index[left], index[right]):
            mst_edges.append([left, right, weight])
            total_weight += weight
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("graph is disconnected")
    return {"mst_edges": mst_edges, "total_weight": total_weight}
